// Regenerates src-tauri/assets/phone-demo.html from phone.html.
// The demo IS the real app with exactly one change: mock mode defaults ON,
// so it boots against the built-in fixture box with no server or token.
// Run after any phone.html change:  node scripts/make-phone-demo.mjs
import { readFileSync, writeFileSync } from "node:fs";

const SRC = "src-tauri/assets/phone.html";
const OUT = "src-tauri/assets/phone-demo.html";
const NEEDLE = 'const MOCK = qs.get("mock") === "1";';
const REPLACEMENT =
  'const MOCK = qs.get("mock") !== "0"; // DEMO: mock ON unless ?mock=0 (generated by scripts/make-phone-demo.mjs)';

const src = readFileSync(SRC, "utf8");
if (!src.includes(NEEDLE)) {
  throw new Error("MOCK line not found in phone.html — update scripts/make-phone-demo.mjs");
}
writeFileSync(OUT, src.replace(NEEDLE, REPLACEMENT));
console.log(OUT + " regenerated from " + SRC);
